13	export function reviewPages(docs) {
14	  const pages = new Map();
15	  for (const doc of docs.documents) {
16	    if (doc.markerKey !== "type" || !declaredType(doc)) continue;
17	    if (doc.path === doc.canonical || !pages.has(doc.canonical))
18	      pages.set(doc.canonical, doc);
19	  }
20	  return pages.values();
21	}
