24	 * retain a link's location when permissions prevent a whole-root inspection.
25	 * @throws for other errors or for focused commands that stop at the first read failure.
26	 */
27	function recordLinkReadError(docs, doc, link, error) {
28	  if (!docs.readErrors || !["EACCES", "EPERM"].includes(error.code))
29	    throw error;
30	  docs.readErrors.add(
31	    `${doc.relative}:${link.line} → ${link.target}: ${error.message}`,
32	  );
33	}
