1	/** shared CLI and document inventory for the documentation checks. */
2	import { readdir, readFile, realpath, stat } from "node:fs/promises";
3	import {
4	  basename,
5	  dirname,
6	  isAbsolute,
7	  join,
8	  relative,
9	  resolve,
10	  sep,
11	} from "node:path";
12	const validators = [
13	  ["check-docs.mjs", "whole-root OKF and engineering validation"],
14	  ["check-index.mjs", "document reachability and OKF concept kinds"],
15	  ["check-references.mjs", "relative links and Markdown fragments"],
16	  ["check-glossary.mjs", "legacy spec/glossary pairing"],
17	];
18	
19	/** list the other checks available from the same standalone installation. */
20	export function siblingHelp(self) {
21	  return (
22	    "\nRelated checks:\n" +
23	    validators
24	      .filter(([name]) => name !== self)
25	      .map(([name, what]) => `  ${name.padEnd(30)} ${what}`)
26	      .join("\n")
27	  );
28	}
29	
30	export function selfName(url) {
31	  return basename(new URL(url).pathname);
32	}
33	
34	/** normalize a legacy domain heading for comparison with its spec filename. */
35	export function slug(value) {
36	  return value
37	    .toLowerCase()
38	    .replace(/[^a-z0-9]+/g, "-")
39	    .replace(/^-+|-+$/g, "");
40	}
41	
42	/** extract inline destinations and ATX level-two headings without parser dependencies. */
43	function readLegacy(text) {
44	  const headings = [],
45	    links = [];
46	  let fence;
47	  for (const [i, line] of text.split("\n").entries()) {
48	    const marker = line.match(/^\s*(`{3,}|~{3,})/)?.[1];
49	    if (fence) {
50	      if (marker?.startsWith(fence)) fence = undefined;
51	      continue;
52	    }
53	    if (marker) {
54	      fence = marker;
55	      continue;
56	    }
57	    const prose = line.replace(/`[^`]*`/g, "");
58	    const heading = prose.match(/^##\s+(.+?)\s*#*\s*$/);
59	    if (heading) headings.push({ level: 2, text: heading[1].trim() });
60	    for (const match of prose.matchAll(
61	      /(!?)\[[^\]]*\]\(\s*([^)\s]+)(?:\s+"[^"]*")?\s*\)/g,
62	    )) {
63	      if (!/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(match[2]))
64	        links.push({ target: match[2], line: i + 1, image: !!match[1] });
65	    }
66	  }
67	  return { headings, links };
68	}
69	
70	/**
71	 * collect Markdown files, optionally deferring hidden entries until the format is known.
72	 * @throws if a directory cannot be read.
73	 */
74	async function listDocuments(dir, inventory) {
75	  const files = [];
76	  let entries;
77	  try {
78	    entries = await readdir(dir, { withFileTypes: true });
79	  } catch (error) {
80	    if (!inventory?.readErrors) throw error;
81	    inventory.readErrors.add(error.message);
82	    return files;
83	  }
84	  for (const entry of entries) {
85	    const path = join(dir, entry.name);
86	    if (inventory && entry.name.startsWith(".")) {
87	      if (entry.isDirectory()) inventory.hiddenDirectories.push(path);
88	      else if (entry.isFile() && path.endsWith(".md"))
89	        inventory.hiddenFiles.push(path);
90	      continue;
91	    }
92	    if (entry.isDirectory())
93	      files.push(...(await listDocuments(path, inventory)));
94	    else if (entry.isFile()) {
95	      if (inventory) inventory.populated = true;
96	      if (path.endsWith(".md")) files.push(path);
97	    } else if (
98	      inventory?.root &&
99	      entry.isSymbolicLink() &&
100	      path.endsWith(".md")
101	    ) {
102	      try {
103	        const actual = await realpath(path);
104	        if (
105	          !bundlePathError(inventory.root, actual) &&
106	          (await stat(actual)).isFile()
107	        ) {
108	          inventory.aliases.set(path, actual);
109	          files.push(path);
110	        }
111	      } catch (error) {
112	        inventory.readErrors.add(error.message);
113	      }
114	    }
115	  }
116	  return files;
117	}
118	
119	/** recognize top-level OKF keys when header parsing fails or YAML is unavailable. */
120	function hasOkfMarker({ text, markerKey: key }) {
121	  if (!key || !/^---[ \t]*\r?\n/.test(text)) return false;
122	  const header = text.split(/^---[ \t]*\r?$/m, 3)[1] ?? "";
123	  const content = header.replace(/^\s*#[^\n]*$/gm, "");
124	  const first = content.match(/^([ ]*)(\S.*)$/m);
125	  if (!first) return false;
126	  const marker = new RegExp(`^(?:\\?\\s+)?(?:"${key}"|'${key}'|${key})\\s*:`);
127	  const explicitKey = new RegExp(
128	    `^\\?[ \\t]+(?:"${key}"|'${key}'|${key})[ \\t]*$`,
129	  );
130	  if (!first[2].startsWith("{"))
131	    return content
132	      .split("\n")
133	      .some(
134	        (line) =>
135	          line.startsWith(first[1]) &&
136	          (marker.test(line.slice(first[1].length)) ||
137	            explicitKey.test(line.slice(first[1].length))),
138	      );
139	
140	  // at depth one, only the text after the opening brace or a comma can be
141	  // the next root key. skip quoted scalars and comments as whole tokens.
142	  let depth = 0;
143	  for (const token of content.matchAll(
144	    /"(?:\\[\s\S]|[^"\\])*"|'(?:''|[^'])*'|(?:^|\s)#[^\n]*|[{},\[\]]/gm,
145	  )) {
146	    const part = token[0];
147	    if (part === "{" || part === "[") depth++;
148	    if (depth === 1 && (part === "{" || part === ",")) {
149	      const tail = content
150	        .slice(token.index + 1)
151	        .replace(/^(?:\s|#[^\n]*\n)*/, "");
152	      if (marker.test(tail)) return true;
153	    }
154	    if (part === "}" || part === "]") depth--;
155	  }
156	  return false;
157	}
158	
159	/**
160	 * inventory the whole root as OKF, or autodetect the format for a focused check.
161	 * @throws if the bundle is outside the supplied source root, its files cannot be read,
162	 * the index is outside the inventory or a recognized OKF bundle cannot load its parsers.
163	 */
164	export async function loadDocs(dir, sourceRoot, { wholeRoot = false } = {}) {
165	  const hasIndex = (
166	    await stat(join(dir, "index.md")).catch(() => null)
167	  )?.isFile();
168	  if (!wholeRoot && !hasIndex) return null;
169	  const root = await realpath(dir);
170	  if (sourceRoot && outside(sourceRoot, root))
171	    throw new Error("--source-root must contain the documentation directory");
172	  const indexPath = join(root, "index.md");
173	  const inventory = {
174	    root: wholeRoot ? root : undefined,
175	    aliases: new Map(),
176	    hiddenDirectories: [],
177	    hiddenFiles: [],
178	    populated: Boolean(hasIndex),
179	    readErrors: wholeRoot ? new Set() : undefined,
180	  };
181	  /**
182	   * read pages in stable order with bundle-relative names for diagnostics.
183	   * @throws if an inventoried file cannot be read.
184	   */
185	  async function readDocuments(paths) {
186	    const pages = [];
187	    for (const path of paths.sort()) {
188	      const name = relative(root, path).split(sep).join("/");
189	      try {
190	        const canonical = inventory.aliases.get(path) ?? path;
191	        const text = (await readFile(canonical, "utf8")).replace(/^\uFEFF/, "");
192	        pages.push({ path, canonical, relative: name, text });
193	      } catch (error) {
194	        if (!wholeRoot) throw error;
195	        inventory.readErrors.add(`${name}: ${error.message}`);
196	      }
197	    }
198	    return pages;
199	  }
200	  const documents = await readDocuments(await listDocuments(root, inventory));
201	  const byPath = new Map(documents.map((doc) => [doc.path, doc]));
202	  const index =
203	    byPath.get(indexPath) ??
204	    (!wholeRoot && hasIndex
205	      ? byPath.get(await realpath(indexPath))
206	      : undefined);
207	  if (hasIndex && !index && !wholeRoot)
208	    throw new Error(
209	      "index.md does not resolve to a visible Markdown document in the bundle",
210	    );
211	  for (const doc of documents) {
212	    if (doc === index) doc.markerKey = "okf_version";
213	    else if (!["index.md", "log.md"].includes(basename(doc.path)))
214	      doc.markerKey = "type";
215	  }
216	  let readMarkdown;
217	  if (wholeRoot || documents.some((doc) => /^---[ \t]*\r?\n/.test(doc.text))) {
218	    try {
219	      ({ readMarkdown } = await import("./okf.mjs"));
220	    } catch (error) {
221	      if (error.code !== "ERR_MODULE_NOT_FOUND") throw error;
222	      if (wholeRoot || documents.some(hasOkfMarker))
223	        throw new Error(
224	          "OKF checks require dependencies. Run npm ci --ignore-scripts in the skill's scripts directory.",
225	        );
226	    }
227	  }
228	  if (readMarkdown) {
