1	import MarkdownIt from "markdown-it";
2	import footnote from "markdown-it-footnote";
3	import parseLicense from "spdx-expression-parse";
4	import { parseFragment } from "parse5";
5	import { parseDocument, isAlias, isMap, LineCounter } from "yaml";
6	
7	const markdown = new MarkdownIt({ html: true }).use(footnote);
8	const external = /^(?:[a-z][a-z0-9+.-]*:|\/\/)/i;
9	
10	/** collect concept path fields and the root license file with their YAML use sites. */
11	function readPathFields(meta, syntax, lineCounter, markerKey, wholeRoot) {
12	  const links = [];
13	  /** retain local path fields separately from links that an index can use for navigation. */
14	  function add(keys, target, error) {
15	    if (typeof target !== "string") return;
16	    if (!error && (!target || external.test(target))) return;
17	    // §5.1 also permits a human-readable population descriptor here.
18	    // spaces in a URI reference must be percent-encoded.
19	    if (keys[0] === "sources" && /\s/.test(target)) return;
20	    // an alias of an entire source list has one use site for all its paths.
21	    let node = syntax;
22	    for (const key of keys) {
23	      if (isAlias(node)) break;
24	      const child = node.get?.(key, true);
25	      if (!child) break;
26	      node = child;
27	    }
28	    const line = 1 + lineCounter.linePos(node.range[0]).line;
29	    links.push({ target, line, field: keys.join("."), error });
30	  }
31	  const license = meta.get("license");
32	  if (markerKey === "okf_version" && typeof license === "string") {
33	    try {
34	      parseLicense(license);
35	    } catch {
36	      const error =
37	        !license.trim() || external.test(license.trim())
38	          ? "must name an SPDX expression or a file in the bundle"
39	          : undefined;
40	      add(["license"], license, error);
41	    }
42	  }
43	  if (markerKey !== "type" || (!wholeRoot && !meta.has("type"))) return links;
44	  for (const key of ["resource", "computation", "superseded_by"])
45	    add([key], meta.get(key));
46	  for (const key of ["executor", "attester"])
47	    add([key, "resource"], meta.get(key)?.get?.("resource"));
48	  const sources = meta.get("sources");
49	  if (Array.isArray(sources)) {
50	    sources.forEach((source, i) =>
51	      add(["sources", i, "resource"], source?.get?.("resource")),
52	    );
53	  } else if (sources instanceof Map) {
54	    add(["sources", "resource"], sources.get("resource"));
55	  }
56	  return links;
57	}
58	
59	/**
60	 * collect rendered anchors, including generated footnotes, and map active
61	 * authored links back to their Markdown or HTML source lines.
62	 */
63	function collectNavigation(tokens, env, fragments, anchors, links) {
64	  const sources = new Map();
65	  let shift = 0;
66	  const rendered = markdown.renderer.render(tokens, markdown.options, env);
67	  const html = rendered.replace(/\0(\d+)\0/g, (marker, id, position) => {
68	    const fragment = fragments[id];
69	    let line = fragment.line;
70	    for (const match of fragment.content.matchAll(/[<\n]/g)) {
71	      if (match[0] === "\n") line++;
72	      else
73	        sources.set(position + shift + match.index, {
74	          line,
75	          html: fragment.html,
76	        });
77	    }
78	    shift += fragment.content.length - marker.length;
79	    return fragment.content;
80	  });
81	
82	  const pending = [parseFragment(html, { sourceCodeLocationInfo: true })];
83	  while (pending.length) {
84	    const element = pending.pop();
85	    const source = sources.get(
86	      element.sourceCodeLocation?.startTag?.startOffset,
87	    );
88	    for (const { name, value } of element.attrs ?? []) {
